static const char *const tern_std_chunks_33[] = {
    "package std::io\n"
    "\n"
    "/// WS2812/WS2812B (\"NeoPixel\") LED chain driver.\n"
    "///\n"
    "/// * Each `in` beat is one LED: 24 bits as 0xGGRRBB (the chip's wire order),\n"
    "///   sent MSB first.\n"
    "/// * Bit timing is derived from `ClkHz`: a bit lasts 1.25 us; a 0 is high for\n"
    "///   0.40 us, a 1 for 0.80 us (datasheet: +-150 ns), the rest of the bit low.\n"
    "/// * Pixels offered back to back are sent without a gap: the next pixel is\n"
    "///   accepted in the last cycle of the previous one's last bit.\n"
    "/// * When no pixel is waiting at that point the frame ends: the line is held\n"
    "///   low for `ResetUs` microseconds, which latches the colours into the LEDs,\n"
    "///   and only then is the next pixel accepted. Use `ResetUs` = 50 for original\n"
    "///   WS2812, 280 (default) for WS2812B and later revisions.\n"
    "/// * Within a frame the producer must therefore keep `in.valid` high (e.g. by\n"
    "///   reading from a FIFO); a stall ends the frame.\n"
    "pub module Ws2812<ClkHz: uint, ResetUs: uint = 280> {\n"
    "    /// Clock cycles per bit (1.25 us).\n"
    "    pub const T_BIT: uint = ClkHz * 125 / 100_000_000\n"
    "    /// High time of a 0 bit (0.40 us), in cycles.\n"
    "    pub const T0H: uint = ClkHz * 40 / 100_000_000\n"
    "    /// High time of a 1 bit (0.80 us), in cycles.\n"
    "    pub const T1H: uint = ClkHz * 80 / 100_000_000\n"
    "    /// Low time that latches the frame, in cycles.\n"
    "    pub const T_RESET: uint = ClkHz * ResetUs / 1_000_000\n"
    "    static_assert(ClkHz >= 5_000_000, \"Ws2812: needs a clock of at least 5 MHz\")\n"
    "    static_assert(T_RESET >= 1, \"Ws2812: ResetUs must be at least 1\")\n"
    "    /// Cycles from the `in` handshake to the first rising edge on `dout`.\n"
    "    pub const LATENCY: uint = 1\n"
    "\n"
    "    /// Clock at `ClkHz`.\n"
    "    in clk: clock\n"
    "    /// Reset: line low, no frame in progress.\n"
    "    in rst: reset\n"
    "    /// Pixels, 0xGGRRBB.\n"
    "    in in: Stream<uint<24>>\n"
    "    /// Data line to the first LED.\n"
    "    out dout: bool\n"
    "    /// High while a frame is being sent or latched.\n"
    "    out busy: bool\n"
    "\n"
    "    enum State { Idle, Bit, Latch }\n"
    "    reg state: State = .Idle\n"
    "    reg shift: uint<24> = 0\n"
    "    reg bit_idx: uint<5> = 0\n"
    "    reg cnt: uint<clog2(T_BIT)> = 0\n"
    "    reg rcnt: uint<clog2(T_RESET + 1)> = 0\n"
    "\n"
    "    let bit_end = cnt == T_BIT - 1\n"
    "    let last_bit = bit_idx == 23\n"
    "    let high_time: uint<clog2(T_BIT)> = if shift[23] { T1H } else { T0H }\n"
    "\n"
    "    in.ready = state == .Idle or (state == .Bit and bit_end and last_bit)\n"
    "    dout = state == .Bit and cnt < high_time\n"
    "    busy = state != .Idle\n"
    "\n"
    "    on clk {\n"
    "        match state {\n"
    "            .Idle => if in.valid {\n"
    "                shift = in.data\n"
    "                bit_idx = 0\n"
    "                cnt = 0\n"
    "                state = .Bit\n"
    "            },\n"
    "            .Bit => {\n"
    "                cnt = if bit_end { 0 } else { cnt +% 1 }\n"
    "                if bit_end {\n"
    "                    if !last_bit {\n"
    "                        shift = shift << 1\n"
    "                        bit_idx = bit_idx +% 1\n"
    "                    } else if in.valid {\n"
    "                        shift = in.data\n"
    "                        bit_idx = 0\n"
    "                    } else {\n"
    "                        rcnt = 0\n"
    "                        state = .Latch\n"
    "                    }\n"
    "                }\n"
    "            },\n"
    "            .Latch => if rcnt == T_RESET - 1 { state = .Idle } else { rcnt = rcnt +% 1 },\n"
    "        }\n"
    "    }\n"
    "\n"
    "    /// The line is low while latching.\n"
    "    property latch_low { always state == .Latch |-> !dout }\n"
    "    /// An accepted pixel starts with a high pulse in the next cycle.\n"
    "    property accept_starts_bit { always in.fire() |=> state == .Bit and dout }\n"
    "    /// No pixel is accepted mid-pixel.\n"
    "    property accept_only_at_pixel_boundary {\n"
    "        always (state == .Bit and !(bit_end and last_bit)) |-> !in.ready\n"
    "    }\n"
    "}\n"
    "\n"
    "test \"Ws2812 encodes 0 and 1 bits with the datasheet high times\" {\n"
    "    let dut = sim Ws2812<ClkHz: 20_000_000, ResetUs: 50>()   // T_BIT 25, T0H 8, T1H 16\n"
    "    dut.reset()\n"
    "    let v: uint<24> = 0xA5_3C_F0\n"
    "    dut.in = Stream { valid: true, data: v }\n"
    "    dut.step()\n"
    "    dut.in.valid = false\n"
    "    for i in 0..24 {\n"
    "        var high = 0\n"
    "        for _ in 0..25 {\n",
    "            if dut.dout { high = high + 1 }\n"
    "            dut.step()\n"
    "        }\n"
    "        expect high == (if v[23 - i] { 16 } else { 8 })\n"
    "    }\n"
    "    expect dut.busy and !dut.dout                      // latching\n"
    "}\n"
    "\n"
    "test \"Ws2812 latches for ResetUs after the last pixel\" {\n"
    "    let dut = sim Ws2812<ClkHz: 20_000_000, ResetUs: 50>()   // T_RESET 1000\n"
    "    dut.reset()\n"
    "    dut.in = Stream { valid: true, data: 0x000000 }\n"
    "    dut.step()\n"
    "    dut.in.valid = false\n"
    "    dut.step(24 * 25)\n"
    "    expect dut.busy and !dut.in.ready\n"
    "    for _ in 0..999 {\n"
    "        expect !dut.dout and !dut.in.ready\n"
    "        dut.step()\n"
    "    }\n"
    "    dut.step()\n"
    "    expect !dut.busy and dut.in.ready\n"
    "}\n"
    "\n"
    "test \"Ws2812 sends back-to-back pixels without a gap\" {\n"
    "    let dut = sim Ws2812<ClkHz: 20_000_000, ResetUs: 50>()\n"
    "    dut.reset()\n"
    "    let pixels = [0xFFFFFF, 0x000001]\n"
    "    var accepted = 0\n"
    "    var highs = 0\n"
    "    var rises = 0\n"
    "    var last = false\n"
    "    dut.in = Stream { valid: true, data: pixels[0] }\n"
    "    for _ in 0..(2 * 24 * 25 + 1) {\n"
    "        let fire = dut.in.valid and dut.in.ready\n"
    "        if dut.dout { highs = highs + 1 }\n"
    "        if dut.dout and !last { rises = rises + 1 }\n"
    "        last = dut.dout\n"
    "        dut.step()\n"
    "        if fire {\n"
    "            accepted = accepted + 1\n"
    "            if accepted == 1 { dut.in.data = pixels[1] } else { dut.in.valid = false }\n"
    "        }\n"
    "    }\n"
    "    expect accepted == 2\n"
    "    expect rises == 48                                 // one rising edge per bit, no missing bit\n"
    "    expect highs == 24 * 16 + 23 * 8 + 16\n"
    "}\n"
};

