static const char *const tern_std_chunks_53[] = {
    "package std::video\n"
    "\n"
    "/// 24-bit RGB pixel, 8 bits per channel. Packed as `r ++ g ++ b`\n"
    "/// (`bits(c)` is the usual 0xRRGGBB).\n"
    "pub struct Rgb888 {\n"
    "    r: u8,\n"
    "    g: u8,\n"
    "    b: u8,\n"
    "}\n"
    "\n"
    "/// 16-bit RGB pixel, 5-6-5 bits. Packed as `r ++ g ++ b`, so `bits(c)` is\n"
    "/// the standard RGB565 word and `Rgb565::from_bits(w)` unpacks one.\n"
    "pub struct Rgb565 {\n"
    "    r: uint<5>,\n"
    "    g: uint<6>,\n"
    "    b: uint<5>,\n"
    "}\n"
    "\n"
    "/// Converts RGB888 to RGB565 by dropping the low bits of each channel.\n"
    "pub fn rgb888_to_565(c: Rgb888) -> Rgb565 {\n"
    "    Rgb565 { r: c.r[7:3], g: c.g[7:2], b: c.b[7:3] }\n"
    "}\n"
    "\n"
    "/// Scales an 8-bit channel to the nearest of the 2^N levels of an N-bit\n"
    "/// channel: round(v \302\267 (2^N - 1) / 255). (Division by a constant.)\n"
    "fn round_channel<N: uint>(v: u8) -> uint<N> {\n"
    "    ((v * ((1 << N) - 1) + 127) / 255) as uint<N>\n"
    "}\n"
    "\n"
    "/// Converts RGB888 to RGB565 rounding each channel to the nearest level\n"
    "/// (round(v \302\267 31 / 255) and round(v \302\267 63 / 255)); the inverse of\n"
    "/// [rgb565_to_888] up to rounding, so a 565 -> 888 -> 565 round trip is exact.\n"
    "pub fn rgb888_to_565_round(c: Rgb888) -> Rgb565 {\n"
    "    Rgb565 { r: round_channel<5>(c.r), g: round_channel<6>(c.g), b: round_channel<5>(c.b) }\n"
    "}\n"
    "\n"
    "/// Expands RGB565 to RGB888 by bit replication (the top bits repeat in the\n"
    "/// low bits), so 0 maps to 0 and full scale maps to 255.\n"
    "pub fn rgb565_to_888(c: Rgb565) -> Rgb888 {\n"
    "    Rgb888 { r: c.r ++ c.r[4:2], g: c.g ++ c.g[5:4], b: c.b ++ c.b[4:2] }\n"
    "}\n"
    "\n"
    "/// Builds an RGB888 pixel from a 0xRRGGBB word.\n"
    "pub fn rgb888_from_hex(v: uint<24>) -> Rgb888 {\n"
    "    Rgb888::from_bits(v)\n"
    "}\n"
    "\n"
    "/// Luma (BT.601, integer approximation): (77\302\267R + 150\302\267G + 29\302\267B) / 256.\n"
    "pub fn luma(c: Rgb888) -> u8 {\n"
    "    ((c.r * 77 + c.g * 150 + c.b * 29) >> 8) as u8\n"
    "}\n"
    "\n"
    "test \"888 to 565 truncates\" {\n"
    "    let c = rgb888_to_565(Rgb888 { r: 0xFF, g: 0x80, b: 0x07 })\n"
    "    expect c.r == 31 and c.g == 32 and c.b == 0\n"
    "    expect bits(rgb888_to_565(Rgb888 { r: 0xFF, g: 0xFF, b: 0xFF })) == 0xFFFF\n"
    "}\n"
    "\n"
    "test \"888 to 565 rounding picks the nearest level\" {\n"
    "    let c = rgb888_to_565_round(Rgb888 { r: 0xFF, g: 0x81, b: 0x05 })\n"
    "    expect c.r == 31          // full scale stays full scale\n"
    "    expect c.g == 32          // 129 \302\267 63 / 255 = 31.9\n"
    "    expect c.b == 1           // 5 \302\267 31 / 255 = 0.61\n"
    "    expect rgb888_to_565_round(Rgb888 { r: 4, g: 0, b: 0 }).r == 0   // 0.49 rounds down\n"
    "}\n"
    "\n"
    "test \"565 to 888 replicates bits\" {\n"
    "    let w = rgb565_to_888(Rgb565 { r: 31, g: 63, b: 31 })\n"
    "    expect w.r == 255 and w.g == 255 and w.b == 255\n"
    "    let k = rgb565_to_888(Rgb565 { r: 0, g: 0, b: 0 })\n"
    "    expect k.r == 0 and k.g == 0 and k.b == 0\n"
    "    let m = rgb565_to_888(Rgb565 { r: 0b10000, g: 0b100000, b: 0b00001 })\n"
    "    expect m.r == 0b1000_0100 and m.g == 0b1000_0010 and m.b == 0b0000_1000\n"
    "}\n"
    "\n"
    "test \"565 round trip is lossless\" {\n"
    "    for _ in 0..256 {\n"
    "        let c = Rgb565::from_bits(rand<u16>())\n"
    "        expect bits(rgb888_to_565(rgb565_to_888(c))) == bits(c)\n"
    "        expect bits(rgb888_to_565_round(rgb565_to_888(c))) == bits(c)\n"
    "    }\n"
    "}\n"
    "\n"
    "test \"packing order is r g b from the top\" {\n"
    "    let c = rgb888_from_hex(0x123456)\n"
    "    expect c.r == 0x12 and c.g == 0x34 and c.b == 0x56\n"
    "    expect bits(Rgb565 { r: 1, g: 0, b: 0 }) == 0x0800\n"
    "}\n"
    "\n"
    "test \"luma of grey levels\" {\n"
    "    expect luma(Rgb888 { r: 0, g: 0, b: 0 }) == 0\n"
    "    expect luma(Rgb888 { r: 255, g: 255, b: 255 }) == 255\n"
    "    expect luma(Rgb888 { r: 100, g: 100, b: 100 }) == 100\n"
    "}\n"
};

