const char *tern_std_text(size_t i)
{
    static char *cache[58];
    const StdEmbedFile *f;
    size_t k, off = 0;
    if (i >= tern_std_file_count)
        return NULL;
    if (cache[i])
        return cache[i];
    f = &tern_std_files[i];
    cache[i] = (char *)xmalloc(f->len + 1);
    for (k = 0; k < f->nchunks; k++) {
        size_t n = strlen(f->chunks[k]);
        memcpy(cache[i] + off, f->chunks[k], n);
        off += n;
    }
    cache[i][off] = '\0';
    return cache[i];
}
